mapper.select:
        SELECT
            max(ACCT_NO)
        FROM
            PTL_CAPACCT_INFO
        WHERE PORTFOLIO_ID = #{portfolioId}

	                AND ACCT_TYPE = #{acctType}


	                AND CCY = #{ccy}

SELECT SUM(nvl(T.AMOUNT,0)) POSITION
FROM FIN_PRODUCT FP
LEFT JOIN PTL_SEC_POSITION T
ON FP.FINPROD_ID = T.FINPROD_ID
AND T.CDATE = to_date(#{tradeDate}, 'yyyy-mm-dd')
AND T.HODING_TYPE = #{hodingType03}
and T.portfolio_id = #{portfolioId}

    and T.INV_AIM = #{invAim}

WHERE FP.FINPROD_ID = #{finprodId}
GROUP BY T.FINPROD_ID, FP.ISSUE_AMT
